import os
import json
from openai import OpenAI

def extract_json(text: str, schema: dict) -> dict:
    """
    Calls a hosted LLM (OpenAI) to extract structured JSON from text based on a provided schema.
    """
    client = OpenAI(
        api_key=os.getenv("OPENAI_API_KEY"),
        base_url=os.getenv("OPENAI_API_BASE", "https://api.openai.com/v1")
    )

    response = client.chat.completions.create(
        model="gpt-4o", # Using a concrete model identifier
        messages=[
            {"role": "system", "content": "You are an AI assistant that extracts information from text and returns it as a JSON object. The JSON should conform to the provided schema."},
            {"role": "user", "content": f"Extract information from the following text into a JSON object conforming to this schema: {json.dumps(schema)}. Text: {text}"}
        ],
        response_format={ "type": "json_object" }
    )
    return json.loads(response.choices[0].message.content)

import os
from openai import OpenAI
from typing import Iterator

def stream_completion(prompt: str) -> Iterator[str]:
    """
    Streams partial output tokens from a hosted LLM (OpenAI).
    """
    client = OpenAI(
        api_key=os.getenv("OPENAI_API_KEY"),
        base_url=os.getenv("OPENAI_API_BASE", "https://api.openai.com/v1")
    )

    stream = client.chat.completions.create(
        model="gpt-4o", # Using a concrete model identifier
        messages=[
            {"role": "system", "content": "You are a helpful assistant."},
            {"role": "user", "content": prompt}
        ],
        stream=True
    )
    for chunk in stream:
        if chunk.choices[0].delta.content is not None:
            yield chunk.choices[0].delta.content

import os
from openai import OpenAI

def get_openai_client() -> OpenAI:
    """
    Provides a configured OpenAI client.
    """
    return OpenAI(
        api_key=os.getenv("OPENAI_API_KEY"),
        base_url=os.getenv("OPENAI_API_BASE", "https://api.openai.com/v1")
    )

def get_default_model() -> str:
    """
    Returns the default OpenAI model identifier.
    """
    return os.getenv("OPENAI_DEFAULT_MODEL", "gpt-4o")

from typing import List, Dict, Any

# This file can be used to define custom request/response models if the default SDK models
# are not sufficient, or for normalization of data coming in/out of the LLM calls.
# For this task, we rely heavily on the OpenAI SDK's built-in models.

class LLMRequest:
    """
    A placeholder for a generic LLM request structure if custom normalization is needed.
    """
    def __init__(self, prompt: str, model: str, max_tokens: int = 150):
        self.prompt = prompt
        self.model = model
        self.max_tokens = max_tokens

    def to_openai_format(self) -> Dict[str, Any]:
        # Example of how a generic request might be normalized for OpenAI
        return {
            "model": self.model,
            "messages": [{"role": "user", "content": self.prompt}],
            "max_tokens": self.max_tokens
        }

class LLMResponse:
    """
    A placeholder for a generic LLM response structure if custom post-processing/normalization is needed.
    """
    def __init__(self, raw_response: Any):
        self.raw_response = raw_response
        self.text = self._extract_text(raw_response)

    def _extract_text(self, raw_response: Any) -> str:
        # Example of how to extract text from a raw OpenAI response
        try:
            return raw_response.choices[0].message.content
        except (AttributeError, IndexError, TypeError):
            return ""

    def to_dict(self) -> Dict[str, Any]:
        return {
            "text": self.text,
            "raw_response": str(self.raw_response) # Convert raw_response to string for serialization if needed
        }

import os
from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory

def check_safety(text: str) -> dict:
    """
    Checks prompts and generated text for unsafe content using Azure Content Safety.
    """
    endpoint = os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = os.getenv("AZURE_CONTENT_SAFETY_KEY")

    if not endpoint or not key:
        raise ValueError("AZURE_CONTENT_SAFETY_ENDPOINT and AZURE_CONTENT_SAFETY_KEY must be set in environment variables.")

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))

    request = AnalyzeTextOptions(text=text)

    # Example: enable all text categories
    request.categories = [
        TextCategory.HATE,
        TextCategory.SEXUAL,
        TextCategory.SELF_HARM,
        TextCategory.VIOLENCE,
    ]

    response = client.analyze_text(request)

    result = {}
    if response.hate_result:
        result["hate"] = {"severity": response.hate_result.severity}
    if response.sexual_result:
        result["sexual"] = {"severity": response.sexual_result.severity}
    if response.self_harm_result:
        result["self_harm"] = {"severity": response.self_harm_result.severity}
    if response.violence_result:
        result["violence"] = {"severity": response.violence_result.severity}

    return result
